import time
from itertools import combinations

import pytest

import basket
import gen_baskets

MIN_SUPPORT = 0.01


@pytest.fixture(scope="module")
def baskets():
    return gen_baskets.generate_baskets()


@pytest.fixture(scope="module")
def results(baskets):
    return basket.compute_pair_metrics(baskets, MIN_SUPPORT)


def _records_for(results, a, b):
    """All directed records covering the unordered pair {a, b}."""
    return [
        r
        for r in results
        if {r["antecedent"], r["consequent"]} == {a, b}
    ]


def test_planted_pairs_in_top5_by_lift(results):
    top5 = {(r["antecedent"], r["consequent"]) for r in results[:5]}
    assert ("bread", "butter") in top5 or ("butter", "bread") in top5
    assert ("diapers", "beer") in top5 or ("beer", "diapers") in top5


@pytest.mark.parametrize("antecedent,consequent,expected", gen_baskets.PLANTED_RULES)
def test_measured_confidence_near_planted(results, antecedent, consequent, expected):
    rec = next(
        r
        for r in results
        if r["antecedent"] == antecedent and r["consequent"] == consequent
    )
    assert rec["confidence"] == pytest.approx(expected, abs=0.05)


def test_independent_pair_lift_near_one(results):
    a, b = gen_baskets.INDEPENDENT_PAIR
    records = _records_for(results, a, b)
    assert records, "independent pair should clear min_support"
    for r in records:
        assert r["lift"] == pytest.approx(1.0, abs=0.15)


def test_lift_identity_holds_exactly(results):
    """lift must equal confidence / P(consequent) to within 1e-9."""
    for r in results:
        expected = r["confidence"] / r["consequent_support"]
        assert abs(r["lift"] - expected) <= 1e-9


def test_pairs_below_min_support_absent(baskets, results):
    n = len(baskets)
    # every reported pair clears the threshold
    assert all(r["support"] >= MIN_SUPPORT for r in results)

    # independently recompute which pairs clear it, and compare exactly
    sets = [set(t) for t in baskets]
    counts = {}
    for t in sets:
        for a, b in combinations(sorted(t), 2):
            counts[(a, b)] = counts.get((a, b), 0) + 1
    expected_pairs = {p for p, c in counts.items() if c / n >= MIN_SUPPORT}
    reported_pairs = {
        frozenset((r["antecedent"], r["consequent"])) for r in results
    }
    assert reported_pairs == {frozenset(p) for p in expected_pairs}
    # no phantom items / no duplicates: one record per direction per pair
    assert len(reported_pairs) * 2 == len(results)


def test_runtime_under_5_seconds(baskets):
    start = time.perf_counter()
    basket.compute_pair_metrics(baskets, MIN_SUPPORT)
    elapsed = time.perf_counter() - start
    assert elapsed < 5.0, f"took {elapsed:.2f}s"
